import Foundation

private typealias E = EvidenceSeed

/// Follow-up trials for the street takeover story: the same person back in this court on a driving or property charge
/// of a different kind each time, so the return doesn't feel fixed.
extension FollowUpCases {
    static let batchBO: [CaseTemplate] = [takeoverRaceBack, takeoverEludeBack, takeoverFieldBack, takeoverDisperseBack]

    /// Racing on a country road, charged as reckless driving.
    static let takeoverRaceBack = SmallCases.make(
        key: "story.followup.takeoverRaceBack",
        category: .traffic,
        headlines: ["Two Drivers Clocked Racing on Cutler Mill Road", "Organizer of Car Meets Charged After Late-Night Race"],
        law: "recklessDriving",
        spec: "Drove carelessly and heedlessly in willful disregard of the rights and safety of others, at 98 miles per hour in a 55 zone while racing another car, on {DATE}.",
        ages: 20...45,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a deputy clocked two cars side by side on Cutler Mill Road at 1:40 a.m. on {DATE}. {D} was in the left lane at 98 miles per hour in a 55 zone. The other driver, in a red Camaro, was stopped a quarter mile ahead. {D.He} had posted the night before that a 'rolling meet' would run the road.",
        state: [E(.video, 3, "Deputy's Dash Camera", "Two cars side by side at 1:40 a.m., 98 on the radar, {D}'s car in the left lane."),
                E(.digital, 2, "Group Chat Post", "From {DL}'s account the night before: \"Rolling meet on Cutler Mill, 1:30. First one to the creek wins.\""),
                E(.document, 2, "Speed Log", "Radar log: 98 miles per hour, 55 posted, dry road.")],
        defense: [E(.statement, 1, "Just Driving", "{DL} says {D.he} was driving home and the Camaro pulled alongside."),
                  E(.document, 1, "Road Sketch", "A sketch shows a long straight, no side roads, no houses for a mile.")],
        role: "Sheriff's deputy",
        exam: [.direct("Deputy, what first drew your attention on Cutler Mill Road that night?", "\"I was parked at the church lot around 1:40 in the morning when two cars came over the rise side by side, both flat out, and the left one was {DL}'s.\""),
               .direct("How fast were they going?", "\"My radar read 98 miles per hour on the left car, and the road is posted at 55. The other car was right beside it, close enough that the headlights ran together.\""),
               .direct("What were the road conditions?", "\"It was dry and clear, a long straight with no side roads and no houses for a mile. There was nothing out there but those two cars and me.\""),
               .direct("Did you see any other traffic?", "\"No, the road was empty. That is part of why I noticed them, because there was nobody else around and they were using the whole width of it.\""),
               .direct("What does your dash camera show?", "\"It shows two cars side by side for several seconds, then {DL}'s car in the left lane crossing in front of my position. The radar number is burned into the frame.\""),
               .direct("Where did the stop happen?", "\"I lit them up and both cars slowed. {DL} pulled over first, and the red Camaro stopped about a quarter mile ahead of us.\""),
               .direct("What did you learn about the group chat afterward?", "\"A deputy pulled the post from {DL}'s account the night before. It said a rolling meet would run Cutler Mill at 1:30 and the first one to the creek wins.\""),
               .cross("The Camaro was a car length ahead when you stopped them, wasn't it?", "\"It was a little ahead at the end, yes. But for most of the distance they ran even, and {DL} never fell back.\""),
               .cross("Could {DL} have been trying to get away from that Camaro?", "\"I considered that, but the post says otherwise. Someone running from a car does not announce a race on the road the night before.\""),
               .cross("Did {DL} swerve or brake before your lights came on?", "\"Not that I could see. I saw brake lights only after my emergency lights went on, which is when both cars backed off.\""),
               .cross("You did not see the Camaro's driver speak with {DL} before the race, did you?", "\"No, I was not close enough for that. I only know what the post says and what the cars did on the road.\""),
               .cross("Your radar locked onto {DL}'s car, not the Camaro?", "\"It locked on the left lane, which was {DL}'s car. I ran it twice and got the same reading both times.\"")],
        theory: ("{D} raced on a public road and told people in advance.", "{D} was driving home with a car on {D.his} bumper."),
        allocution: "\"That road is the way home from my cousin's, and I was going far too fast. I posted something foolish the night before, and I regret it. I was going ninety-eight in a fifty-five zone, and I put other drivers at risk. I'm sorry to the deputy and to anyone on that road.\"",
        truths: ("{DL} texted the Camaro's driver 'bet' ten minutes before the race.", "The Camaro's own dash camera shows {DL} slowing before the deputy's lights."),
        defendant: [.direct("Why were you on Cutler Mill Road that night?", "\"It is the way home from my cousin's house. I had been there since dinner, and that road is the quickest way back to my place.\""),
               .direct("Did you post anything about a meet?", "\"Yes, I did, the night before. I posted that a rolling meet would run the road. I honestly thought nobody would show up.\""),
               .direct("What was the other car doing as you came down the road?", "\"The Camaro pulled up beside me at the top of the rise and stayed there. I did not plan to race anybody that night.\""),
               .direct("Why did you speed up?", "\"I should not have, and I know that. I was showing off and I let the Camaro push me. I was in a hurry for no good reason.\""),
               .direct("What happened when you saw the deputy's lights?", "\"I backed off right away and pulled over before the Camaro did. I put my hands on the wheel and waited for the deputy to come up.\""),
               .direct("How do you feel about what you did?", "\"I feel foolish and a little scared about it. Somebody could have come over that hill, and I put them in danger.\""),
               .cross("The radar said 98 miles per hour, didn't it?", "\"That is what the radar says, and I did not look at my speedometer. I will not argue with the number.\""),
               .cross("You wrote first one to the creek wins, didn't you?", "\"Yes, I wrote it, and it was meant as a joke for the chat. I did not think anyone would take it seriously.\""),
               .cross("Ten minutes before the race you texted the Camaro's driver the word bet, didn't you?", "\"I sent something short like that, yes. I regret it now, because it looks worse than what I meant by it.\""),
               .cross("You had been to car meets before, hadn't you?", "\"I had been to a few. This one was different because it ended up on a public road and not in a lot.\""),
               .cross("Your last case in this court was in {PRIORDATE}, and you were back on the road anyway?", "\"Yes, and I should have known better. I did not think about the last case that night, and that is on me.\"")],
        openings: ("At 1:40 on the morning of {DATE}, a deputy clocked two cars side by side on Cutler Mill Road, and {D}'s was in the left lane at 98 in a 55 zone. The night before, a post from {DL}'s own account announced a rolling meet and a race to the creek.", "The defense will present a driver for whom Cutler Mill is simply the way home from a cousin's house, a long and empty road. A driver who came over a hill with another car on {D.his} bumper is not the same as an organizer of a race, and the State must prove which one this was."),
        closings: ("The radar says 98, the video shows two cars even, and the post says first to the creek wins. {D} had been in this court before, and the road was still where {D.he} chose to race.", "{D} was driving home on the road {D.he} always takes, and a Camaro pulled alongside. A joke typed into a chat is not a speed, and the State never showed an agreement made on the road itself."),
        timeline: [(-1, "{DL}'s group chat posts a 'rolling meet' on Cutler Mill Road."), (0, "1:30 a.m.: two cars start down the road."), (0, "1:40 a.m.: the deputy clocks 98 and stops both cars."), (14, "The Camaro's dash camera is requested.")],
        identified: "Stopped at the scene.",
        notDone: ["The Camaro's driver was never asked what was said before the race."],
        mood: .wantsConviction)

    /// Running from deputies, charged as felony speeding to elude.
    static let takeoverEludeBack = SmallCases.make(
        key: "story.followup.takeoverEludeBack",
        category: .traffic,
        headlines: ["Driver Flees Deputies Breaking Up Car Meet", "Chase From Outlet Lot Ends in Soybean Field"],
        law: "fleeing",
        spec: "Operated a motor vehicle while fleeing a law enforcement officer in the lawful performance of duties, at more than 15 miles per hour over the limit and with reckless driving, on {DATE}.",
        ages: 20...45,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, deputies were called to a vacant outlet lot on {DATE} where about thirty cars had gathered. When a cruiser pulled in with lights on at 11:50 p.m., {D} drove out the back at 85 in a 35 zone. The chase lasted two miles before {D.his} car dropped into a soybean field. {D.He} says the cruiser never turned on a siren.",
        state: [E(.video, 3, "Dash Camera", "The cruiser's lights are on as {D}'s car leaves the lot; 85 in a 35 on the radar."),
                E(.document, 2, "Deputy's Report", "Lights and siren for the full two miles, then the car left the road."),
                E(.digital, 2, "Group Chat Message", "From {DL}'s account at 11:50 p.m.: \"Cops pulling in, everybody out the back.\"")],
        defense: [E(.statement, 1, "No Siren", "{DL} says there was no siren and the lights were mistaken for a tow truck."),
                  E(.statement, 1, "Spectator", "A bystander says the cruiser's siren was not on in the lot.")],
        role: "Sheriff's deputy",
        exam: [.direct("Deputy, what happened at the outlet lot that night?", "\"We were called to a vacant outlet lot where about thirty cars had gathered. I pulled in with my lights on at 11:50, and {DL}'s car left through the back, fast.\""),
               .direct("How fast was the car going?", "\"The radar read 85 miles per hour on the road behind the lot, which is a 35 zone. It was not a close call, it was more than double the limit.\""),
               .direct("Did you use your siren?", "\"I did. I hit it as {DL} pulled out onto the road, and it ran for the full two miles. You can hear it on the dash camera audio.\""),
               .direct("What lights did your cruiser have?", "\"A full blue light bar and a spotlight. They were on when I entered the lot, and nobody could have taken that for a tow truck.\""),
               .direct("How did the chase end?", "\"{DL}'s car left the pavement and dropped into a soybean field. It slid to a stop and I pulled in behind it and ordered {D.him} out.\""),
               .direct("What did the lot's owner tell you afterward?", "\"He said the meet was not allowed and that he had asked the group to leave the week before. He did not call any tow truck that night.\""),
               .direct("What did the group chat show?", "\"It showed a message from {DL}'s account at 11:50 saying cops were pulling in and everybody should go out the back. That was the exact minute I entered the lot.\""),
               .cross("Your siren was not on inside the lot itself, was it?", "\"That is true. I hit it as {DL} pulled out onto the road, and the dash audio shows the moment I did.\""),
               .cross("So {DL} could have thought the lights belonged to a tow truck?", "\"Not with a blue bar and a spotlight on a marked cruiser. Tow trucks use amber, and the cruiser is plainly a patrol car.\""),
               .cross("A bystander says the siren was off in the lot, doesn't {D.he}?", "\"I heard that, but I never spoke with that person. My report says the siren started at the road, and I stand by that.\""),
               .cross("Did you get a clear view of who drove the other cars?", "\"No, there were thirty cars and most were gone before I pulled up. I followed the one that ran at speed.\""),
               .cross("You never saw {DL} look back at your cruiser, did you?", "\"I could not see inside the car at that distance. I saw only the taillights and the speed.\"")],
        theory: ("{D} ran from deputies at 85 miles per hour.", "{D} didn't know it was police."),
        allocution: "\"I saw lights and thought it was a tow truck, so I did not wait around. When I realized it was a cruiser, I panicked and kept going. I'm sorry for the chase and for the danger to everyone on those roads. I'll never run from lights again.\"",
        truths: ("{DL} was the first to leave and told the others to follow.", "The siren did not start until the cruiser reached the road."),
        defendant: [.direct("Why did you leave the lot?", "\"I saw lights and thought it was a tow truck. Everybody in that lot had been told a tow truck might come, and I was not going to wait around.\""),
               .direct("Did you hear a siren?", "\"I do not remember one. The engines were loud in that lot, and I had music on in the car.\""),
               .direct("When did you realize it was a deputy?", "\"Not until I was out on the road and saw the lights fill my mirror. By then I was already going fast and I panicked.\""),
               .direct("Why did you not stop on the road?", "\"I wanted to get away from the lot first, and then I was scared. I know that is not a good answer, and I regret it.\""),
               .direct("What happened at the end?", "\"I came into a curve too fast and the car dropped into a soybean field. I turned the engine off and put my hands up.\""),
               .direct("Have you been in this court before?", "\"I have, in {PRIORDATE}, and I knew I could not afford another case. That is part of why I panicked and kept going.\""),
               .cross("You told your chat that the cops were pulling in, didn't you?", "\"Somebody else typed that, and I passed it on. I did not write it first.\""),
               .cross("The radar said 85 in a 35, didn't it?", "\"It did. I was not looking at the speedometer, but I will not say the radar is wrong.\""),
               .cross("Two miles is a long way to run from a tow truck, isn't it?", "\"It felt short at the time. I was not thinking clearly, and I should have stopped much sooner.\""),
               .cross("You were the first to leave the lot, weren't you?", "\"I was one of the first. When I saw lights I went out the back, and I did not tell anyone to follow.\""),
               .cross("You never turned to look at the cruiser, did you?", "\"I looked in the mirror, but the lights were blinding at night. I could not see what kind of vehicle it was.\"")],
        openings: ("Thirty cars gathered in a vacant outlet lot, and at 11:50 p.m. a cruiser pulled in with its lights on. {D} left through the back at 85 in a 35 zone, and the chase ran two miles with the siren on until the car dropped into a soybean field.", "The defense will present a driver who saw flashing lights in a lot where a tow truck was expected, and a bystander who says no siren sounded inside it. A person who does not know a deputy is behind {D.him} has not chosen to flee."),
        closings: ("The lights were blue, the siren sounded on the road, and the chat message went out at the exact minute the cruiser entered the lot. Someone with {PRIOR} behind {D.him} knew what a cruiser meant.", "The siren started only after {D} was already on the road, and a bystander says it was silent in the lot. Lights taken for a tow truck, then a panic: the State has not proved a decision to run from an officer."),
        timeline: [(0, "11:50 p.m.: the cruiser pulls in, {DL}'s chat tells everyone to go, and {DL}'s car leaves."), (0, "11:54 p.m.: the car drops into a soybean field."), (1, "The outlet lot's owner confirms the meet was not allowed.")],
        identified: "Arrested at the scene.",
        notDone: ["The bystander who said the siren was off was never interviewed."],
        mood: .wantsConviction)

    /// A field torn up by burnouts, charged as injury to real property.
    static let takeoverFieldBack = SmallCases.make(
        key: "story.followup.takeoverFieldBack",
        category: .property,
        headlines: ["Burnouts Tear Up Farmer's Hayfield", "Car Meet Moves Into Cut Hayfield and Leaves Ruts"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly damaged real property of {V}, a cut hayfield, causing damage of $3,400, on {DATE}.",
        ages: 20...45,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}'s freshly cut hayfield was found torn up on {DATE} by rings of burnouts and deep ruts. A trail camera on the gate shows three cars entering at 11:40 p.m. and leaving at 12:30 a.m. One car's plate is partly visible and matches {DL}'s. {D} says {V}'s son told the group they could use the field.",
        state: [E(.video, 3, "Trail Camera", "Three cars enter the field at 11:40 p.m. and leave at 12:30 a.m.; one plate matches {D}'s in its first four characters."),
                E(.physical, 2, "Ruts and Tire Casts", "Rings of burnouts across half an acre; plaster casts of three sets of tires."),
                E(.document, 2, "Hay Loss Estimate", "$3,400 for re-seeding and lost second cutting."),
                E(.digital, 2, "Group Chat Post", "From {DL}'s account: \"Found a field with an open gate, ten minutes from the lot. Before midnight.\"")],
        defense: [E(.statement, 1, "Permission", "{DL} says {V}'s son told the group the field was fine to use."),
                  E(.document, 1, "Gate Photo", "The gate was open and unchained that night.")],
        role: "Field owner",
        exam: [.direct("What did you find when you walked your hayfield?", "\"The whole east half was torn up, with rings of burnouts and deep ruts across about half an acre. I had just cut it and was counting on a second cutting.\""),
               .direct("Did anyone have permission to be on your field?", "\"No. I never gave anyone permission, and I never even heard of this group until the deputies called me.\""),
               .direct("What did your trail camera show?", "\"It shows three cars coming through the gate at 11:40 at night and leaving at 12:30. They stayed fifty minutes and drove circles the whole time.\""),
               .direct("How did the plate become part of this?", "\"One car's plate is only partly visible on the video, but the first four characters match {DL}'s car. A deputy ran those characters against the registration.\""),
               .direct("What did the damage cost you?", "\"The re-seeding and the lost second cutting come to $3,400. The estimate is in the file from the hay buyer I use every year.\""),
               .direct("What did the deputies find at the field?", "\"They made plaster casts of three sets of tires. They also found that the ruts ran from the gate straight into the open grass.\""),
               .direct("Did you ever speak with {DL}?", "\"No, I have never met {DL}. I only learned the name when it came back from the plate and the group chat post.\""),
               .cross("The gate was open that night, wasn't it?", "\"My son left it open that afternoon after loading hay. He did not give anyone permission to drive on the field.\""),
               .cross("Your son never told anybody the field was fine to use?", "\"He says he never spoke to any of them. I asked him directly and he was clear about it.\""),
               .cross("Isn't it possible he told a friend of a friend?", "\"I suppose anything is possible, but he says no. Even if he had, he is not the owner and cannot grant permission.\""),
               .cross("You cannot say who was driving which car, can you?", "\"No, the camera does not show faces. I can say what the cars did, and one plate matches {DL}.\""),
               .cross("The plate is only partly visible, isn't it?", "\"Yes, four characters out of seven. That is why a deputy ran the registration and compared the make and color too.\"")],
        theory: ("{D} led a meet into a hayfield and tore it up.", "{D} thought the owner's son had given permission."),
        allocution: "\"I heard from a guy that it was fine to drive on that field, and I took his word. I should have asked the owner directly. I'm sorry to {V} for the torn-up hayfield and for the loss. I'll pay for every rut and re-seed it myself.\"",
        truths: ("{DL} posted the field's location and arrived first.", "The owner's son did tell a friend of {DL}'s the field was fine to use."),
        defendant: [.direct("Why did you take your car onto that field?", "\"I heard from a guy at a meet that it was fine to use. I took his word because he sounded sure about it.\""),
               .direct("Who was that guy?", "\"I only know him from meets. I thought he knew the family because he spoke as if he knew the owner's son.\""),
               .direct("Was the gate open when you arrived?", "\"It was open and not chained, so I figured it was meant to be used. I did not see any sign or fence line.\""),
               .direct("What did you do in the field?", "\"A couple of burnouts and some circles. Everybody did the same, and we were all out there for the same reason.\""),
               .direct("What did you do after you left?", "\"I went home. I did not know how bad it looked, and I did not think about re-seeding until the deputies called.\""),
               .direct("Looking back, what should you have done differently?", "\"I should have called the owner myself instead of trusting a stranger's word. I am sorry to {V} for the damage.\""),
               .cross("You posted that the field was ten minutes from the lot with no fence, didn't you?", "\"I did post something like that, because I thought no fence meant open. That was my mistake.\""),
               .cross("You never called the owner, did you?", "\"No. It did not cross my mind until it was too late.\""),
               .cross("You arrived before the others, didn't you?", "\"I was probably first because I live closest. I did not plan the others coming.\""),
               .cross("Fifty minutes is a long time to be doing burnouts on a farmer's field, isn't it?", "\"It felt like twenty to me. Looking at the video, I can see that it was longer.\""),
               .cross("You had a case in this court before, and you still did not ask permission?", "\"That is right, and I should have been much more careful than I was. I did not stop to think this time.\"")],
        openings: ("{V}'s hayfield was freshly cut when a trail camera caught three cars entering the gate at 11:40 p.m. and leaving fifty minutes later. A partial plate on one of them matches {DL}'s car, and a post from {DL}'s account named the field the night before.", "Listen for an open, unchained gate and a driver who was told by another person that the field was fine to use. Believing something false is different from damaging property willfully, and the State will not show otherwise."),
        closings: ("Three cars, fifty minutes, and $3,400 in ruts. A plate, a post, and a gate nobody had a right to drive through all point to {D}.", "A gate left open by the owner's own son and a rumor that the field was free: {D} believed the field was open to use. The State has not proved a willful act against {V}'s property."),
        timeline: [(-2, "{DL}'s account posts the field's location."), (0, "11:40 p.m.: three cars enter through the open gate."), (0, "12:30 a.m.: they leave."), (1, "{V} finds the ruts and sends the trail camera video.")],
        identified: "The trail camera plate matches {DL}'s car.",
        notDone: ["The owner's son and {DL}'s 'guy at a meet' were never confronted with each other."],
        mood: .divided)

    /// Refusing to leave a lot, charged as resisting an officer.
    static let takeoverDisperseBack = SmallCases.make(
        key: "story.followup.takeoverDisperseBack",
        category: .publicOrder,
        headlines: ["Driver Refuses to Clear School Lot, Blocks Cruiser", "Car Meet Organizer Charged After Standoff With Deputies"],
        law: "resisting",
        threshold: 5,
        spec: "Willfully resisted, delayed, and obstructed a public officer, a sheriff's deputy, in discharging a duty of the officer's office, on {DATE}.",
        ages: 20...45,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, deputies were sent to a high school lot on {DATE} where about twenty cars had gathered at 10 p.m. A deputy ordered the group to leave three times. {D} refused each time and parked {D.his} car across the lot's only exit, blocking the cruiser for eleven minutes. {D.He} says the lot was public and the orders weren't clear.",
        state: [E(.video, 3, "Body Camera", "Three orders to leave; {D} refuses and parks across the exit."),
                E(.document, 2, "Deputy's Report", "Eleven minutes of delay before a second cruiser arrived and the car was moved."),
                E(.digital, 2, "Group Chat Message", "From {DL}'s account: \"Stay put. They can't make us leave a public lot.\"")],
        defense: [E(.document, 1, "Lot Sign", "A sign at the lot says only 'No loitering after 11 p.m.'"),
                  E(.statement, 1, "Unclear Orders", "{DL} says the deputy's orders weren't clear over the engines.")],
        role: "Sheriff's deputy",
        exam: [.direct("Deputy, why were you sent to the school lot that night?", "\"The school had asked us to clear the lot after 9 p.m., and about twenty cars had gathered there by 10. I arrived with a second cruiser on the way.\""),
               .direct("What did you say to the group?", "\"I used my loudspeaker and ordered everyone to leave, three times in about ten minutes. Most of the cars started to move after the second order.\""),
               .direct("How did {DL} respond?", "\"{DL} stayed put, said the lot was public, and told me to make {D.him} leave. Then {DL} parked across the lot's only exit.\""),
               .direct("How long was your cruiser blocked?", "\"Eleven minutes, until the second cruiser arrived and we got the car moved. The whole time {DL} sat in the driver's seat and refused to move.\""),
               .direct("What does your body camera show?", "\"It shows all three orders and {DL}'s answers. It also shows the car crossing the exit at 10:25 and staying there.\""),
               .direct("Was the lot open to the public?", "\"Yes, during the day. After 9 p.m. the school asked us to clear it, and a sign at the entrance said the lot closed then.\""),
               .cross("The sign at the lot says no loitering after 11, doesn't it?", "\"It does. The school's request came by phone, so I was acting on that and not on the sign.\""),
               .cross("Engines were running all over the lot, weren't they?", "\"A few were, but I was using my loudspeaker and {DL} answered me directly. That tells me {DL} heard.\""),
               .cross("Did you have the school's request in writing?", "\"No, it was a phone call to dispatch. I have never seen it in writing and did not ask for it.\""),
               .cross("{DL} asked you what law was broken, did {D.he} not?", "\"{D.He} did, and I told {D.him} that the school had asked the lot be cleared and that refusing a lawful order was an offense.\""),
               .cross("Your body camera microphone picked up your own voice, not {DL}'s, most clearly, didn't it?", "\"That is fair, my voice is loudest. But {DL}'s answers can be heard, and so can the make us.\"")],
        theory: ("{D} refused three orders and blocked a cruiser.", "{D} didn't understand the orders."),
        allocution: "\"I thought that lot was public property, and I did not understand that I had to leave. I parked across the exit without thinking about the cruiser behind me. I'm sorry for blocking the deputy for eleven minutes. I'll listen the first time I'm asked.\"",
        truths: ("{DL} told the others to stay and set the block on purpose.", "The loudspeaker was too quiet to carry over the engines."),
        defendant: [.direct("Why did you stay in the lot?", "\"I thought it was public property. A lot with no gate and no sign about closing at ten seemed open to me.\""),
               .direct("Did you hear the deputy's orders?", "\"I heard part of them. The engines were loud and I could not make out everything the loudspeaker said.\""),
               .direct("Why was your car across the exit?", "\"I was parking there already when the deputy arrived. I did not do it to block anyone on purpose.\""),
               .direct("What did you ask the deputy?", "\"I asked what law I had broken, and I did not get an answer I understood. I was trying to understand, not to argue.\""),
               .direct("What did you say to your friends?", "\"I told them to stay put because I thought we had a right to be there. I said it to my friends, not to challenge anyone.\""),
               .direct("What do you wish you had done?", "\"I wish I had moved the car the first time I was asked. I am sorry I blocked the deputy for eleven minutes.\""),
               .cross("You told the deputy to make you leave, didn't you?", "\"I said that, and I regret it. I was embarrassed in front of everyone.\""),
               .cross("You posted that they could not make anyone leave, correct?", "\"Yes, I posted that. I believed it when I wrote it, but it was wrong.\""),
               .cross("Eleven minutes passed before you moved, didn't they?", "\"That is what the report says. It felt shorter to me, but I will not dispute it.\""),
               .cross("You were the only car across the exit, weren't you?", "\"Yes. The others had started to move by then.\""),
               .cross("You have been in this court before, and you still stood your ground?", "\"Yes, and that was my mistake. I should have listened the first time.\"")],
        openings: ("About twenty cars filled a school lot at 10 p.m., and the deputy ordered the group to leave three times. {D} answered that it was a public lot, parked across the only exit, and held a cruiser for eleven minutes.", "The defense evidence is a lot with a sign that says only no loitering after 11 p.m. and orders given over running engines. A person who did not understand an order has not willfully resisted a deputy."),
